//! @file
//! @brief carb.logging channel support
#pragma once

#include <cstdint>

/**
 * Creates an extern reference to a log channel defined with \ref CARB_LOG_ADD_CHANNEL.
 * \details Must be used at global scope. May be used multiple times within the same module to reference the same log
 * channel.
 * @see CARB_LOG_ADD_CHANNEL
 * The \ref CARB_LOG macro can then be used to reference the channel:
 * @code{.cpp}
 *   CARB_LOG_DECLARE_CHANNEL(kExtraInfo); // defined elsewhere with CARB_LOG_ADD_CHANNEL
 *
 *   //...
 *
 *   CARB_LOG(kExtraInfo, "Additional context: %p", context);
 * @endcode
 * @param varName The variable name used with \ref CARB_LOG_ADD_CHANNEL.
 */
#define CARB_LOG_DECLARE_CHANNEL(varName) extern ::carb::logging::detail::LogChannelData varName

/**
 * Defines the properties of a log channel and adds it to a module-specific list of channels.
 * \details Must be used at global scope and will run static initializers.
 * @see CARB_LOG_DECLARE_CHANNEL
 * The \ref CARB_LOG macro can then reference the channel:
 * @code{.cpp}
 *   CARB_LOG_ADD_CHANNEL(kExtraInfo, "carb.log.extraInfo", "Extra info for carb.log");
 *
 *   // ...
 *
 *   CARB_LOG(kExtraInfo, "Additional context: %p", context);
 * @endcode
 * @param varName The variable name used to reference the log channel.
 * @param channelName A literal string giving the name of the channel. The name is used to reference the channel, such
 *   as for Settings.
 * @param description A literal string giving the human-readable description of the channel.
 */
#define CARB_LOG_ADD_CHANNEL(varName, channelName, description)                                                        \
    ::carb::logging::detail::LogChannelData varName{ ("" channelName), 0, ("" description), nullptr };                 \
    static ::carb::logging::detail::LogChannelRegistrar varName##_Registrar(&(varName))

#ifndef CARB_LOG_DEFAULT_CHANNEL
//! The default log channel variable to use when no channel is supplied to the `CARB_LOG_*` macros.
//! \details The default channel variable is `g_defaultLogChannel`. It is automatically declared.
#    define CARB_LOG_DEFAULT_CHANNEL g_defaultLogChannel
#endif

//! \cond DEV
namespace carb::logging::detail
{

struct LogChannelData
{
    const char* const name;
    int32_t level;
    const char* const description;
    LogChannelData* next;
};

struct DefaultLogChannelData : public LogChannelData
{
    DefaultLogChannelData() : LogChannelData{ "<default>", 0, "Default log channel", nullptr }
    {
    }
};

inline LogChannelData*& logChannelHead() noexcept
{
    static LogChannelData* head = nullptr;
    return head;
}

inline bool& logChannelsRegistered() noexcept
{
    static bool registered{ false };
    return registered;
}

} // namespace carb::logging::detail
//! \endcond
